package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class PublicFractionArithmeticTest {
 @Test public void wrongFractionPartsAreDerivedFromPublicOperands(){for(String id:List.of("fracAddLike","fracSubLike","fracAdd","fracSub")){boolean like=id.endsWith("Like"),add=id.startsWith("fracAdd");Question q=new Question(id,like?"(5/6) "+(add?"+":"-")+" (1/6)":"(5/6) "+(add?"+":"-")+" (1/4)","poison","poison");int n=like?(add?6:4):(add?13:7),d=like?6:12;assertEquals(1,FractionInput.errorPart(q,(n+1)+"/"+d));assertEquals(2,FractionInput.errorPart(q,n+"/"+(d+1)));assertEquals(0,FractionInput.errorPart(q,n+"/"+d));assertEquals(0,FractionInput.errorPart(q,"99/97"));assertEquals(0,FractionInput.errorPart(q,"/"));}}

 @Test public void allProperPairsIgnoreSavedKeys(){int count=0;for(String id:List.of("fracAddLike","fracSubLike","fracAdd","fracSub"))for(int b=2;b<=12;b++)for(int d=2;d<=12;d++){if(id.endsWith("Like")?b!=d:b==d)continue;for(int a=1;a<b;a++)for(int c=1;c<d;c++){boolean add=id.startsWith("fracAdd");if(!add&&a*d<c*b)continue;int numerator=add?a*d+c*b:a*d-c*b;Question q=new Question(id,"("+a+"/"+b+") "+(add?"+":"-")+" ("+c+"/"+d+")","poison","poison");Checker checker=new Checker();assertTrue(checker.check(q,List.of(),List.of(numerator+"/"+(b*d))).correct());Checker.Result r=checker.check(q,List.of(),List.of((numerator+1)+"/"+(b*d)));assertEquals(Checker.Status.WRONG_ANSWER,r.status);assertEquals(0,r.index);count++;}}assertTrue(count>6000);System.out.println("All proper fraction operation conditions="+count);}
 @Test public void selectedYearFiveSuppliesHundredFreshEach(){for(String id:List.of("fracAddLike","fracSubLike","fracAdd","fracSub")){Generator gen=new Generator(new Random(178));List<String> recent=new ArrayList<>();boolean overOne=false;for(int i=0;i<100;i++){Question q=gen.next(id,recent,false,GlobalCurriculum.limits("england-primary-2021-v1",id,5));assertFalse(recent.contains(q.signature()));recent.add(q.signature());int[] v=PublicFractionArithmetic.givens(q);assertNotNull(v);if(!id.endsWith("Like"))assertTrue(java.math.BigInteger.valueOf(v[1]).gcd(java.math.BigInteger.valueOf(v[3])).intValue()>=2);int n=id.startsWith("fracAdd")?v[0]*v[3]+v[2]*v[1]:v[0]*v[3]-v[2]*v[1];Rational expected=Rational.of(n,v[1]*v[3]);overOne|=expected.compareTo(Rational.of(1))>0;q.answers=new String[]{"999"};String answer=expected.toString();if("fraction".equals(q.answerFormat)&&!answer.contains("/"))answer+="/1";assertTrue(q.prompt+" format="+q.answerFormat,new Checker().check(q,List.of(),List.of(answer)).correct());HelpPlan plan=HelpPlan.forQuestion(q);assertNotNull(plan);assertFalse(plan.canTransfer());assertTrue(plan.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}if(id.startsWith("fracAdd"))assertTrue(overOne);}}
 @Test public void equivalentAnswersAndReductionRulesArePreserved(){Question q=new Question("fracAdd","(1/2) + (1/4)","","999");Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of("6/8")).correct());q.kind="reduced";assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("6/8")).status);assertTrue(c.check(q,List.of(),List.of("3/4")).correct());assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("0.75")).status);assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),Arrays.asList((String)null)).status);q.prompt="(999999999999999999/2) + (1/4)";assertNull(PublicFractionArithmetic.givens(q));}
}
